const resultado = $input.first().json;

const {
  request_id,
  cliente,
  profesional,
  fecha,
  hora,
  duracion_minutos,
  disponible,
  estado,
  conflictos = [],
  event_id
} = resultado;

const fechaFormateada = fecha
  ? new Intl.DateTimeFormat('es-AR', {
      weekday: 'long',
      day: 'numeric',
      month: 'long',
      timeZone: 'UTC'
    }).format(new Date(`${fecha}T12:00:00Z`))
  : 'No especificada';

let mensaje;
let estadoFinal;

// Solo confirmar si Google Calendar creó el evento
const reservaCreada = Boolean(
  event_id || resultado.evento_creado === true
);

if (reservaCreada) {
  estadoFinal = 'confirmada';

  mensaje = [
    '✂️ *Tendencia Urbana*',
    '',
    '✅ ¡Tu reserva está confirmada!',
    '',
    `👤 *Cliente:* ${cliente}`,
    `💈 *Profesional:* ${profesional}`,
    `📅 *Día:* ${fechaFormateada}`,
    `🕥 *Horario:* ${hora} hs`,
    `⏱️ *Duración:* ${duracion_minutos} minutos`,
    '',
    '¡Te esperamos! 💈'
  ].join('\n');

} else if (disponible === false || estado === 'no_disponible') {
  estadoFinal = 'no_disponible';

  mensaje = [
    '✂️ *Tendencia Urbana*',
    '',
    '😔 El horario solicitado ya está reservado.',
    '',
    `💈 *Profesional:* ${profesional}`,
    `📅 *Día:* ${fechaFormateada}`,
    `🕥 *Horario:* ${hora} hs`,
    '',
    '💈 ¿Querés consultar otro horario?'
  ].join('\n');

} else {
  estadoFinal = 'pendiente';

  mensaje = [
    '✂️ *Tendencia Urbana*',
    '',
    '⚠️ No pudimos confirmar tu reserva.',
    '',
    'Por favor, intentá nuevamente.'
  ].join('\n');
}

return [{
  json: {
    request_id,
    intent: 'crear_reserva',
    cliente,
    profesional,
    fecha,
    hora,
    duracion_minutos,
    disponible,
    estado: estadoFinal,
    reserva_confirmada: reservaCreada,
    conflictos,
    mensaje
  }
}];

const resultado = $input.first().json;

const {
  request_id,
  profesional,
  fecha,
  hora,
  duracion_minutos,
  disponible,
  estado
} = resultado;

// Formatear fecha en español argentino
const fechaFormateada = new Intl.DateTimeFormat('es-AR', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  timeZone: 'UTC'
}).format(new Date(`${fecha}T12:00:00Z`));

// Determinar disponibilidad
const estaDisponible = disponible === true;

// Preparar mensaje para WhatsApp
let mensaje;

if (estaDisponible) {
  mensaje = [
    '✂️ *Tendencia Urbana*',
    '',
    '✅ ¡Tenemos disponibilidad!',
    '',
    `👤 *Profesional:* ${profesional}`,
    `📅 *Día:* ${fechaFormateada}`,
    `🕥 *Horario:* ${hora} hs`,
    `⏱️ *Duración:* ${duracion_minutos} minutos`,
    '',
    '💈 ¿Querés que reservemos este turno para vos?'
  ].join('\n');

} else {
  mensaje = [
    '✂️ *Tendencia Urbana*',
    '',
    '😔 El horario solicitado no está disponible.',
    '',
    `👤 *Profesional:* ${profesional}`,
    `📅 *Día:* ${fechaFormateada}`,
    `🕥 *Horario:* ${hora} hs`,
    '',
    '💈 ¿Querés consultar otro horario?'
  ].join('\n');
}

// Respuesta estructurada para el Webhook
return [{
  json: {
    request_id,
    intent: 'consultar_disponibilidad',
    profesional,
    fecha,
    hora,
    duracion_minutos,
    disponible: estaDisponible,
    estado,
    mensaje
  }
}];

