parameters.jsCode:
const item = $input.first().json;

const sessionId = String(
  $('Set | Entrada común').first().json.session_id
);

const registro = $('Airtable | Actualizar Cliente').first().json;

const datos = JSON.parse(
  registro.fields?.['Datos clave'] || '{}'
);

const messageCount = Number(datos.message_count || 0) + 1;

return [{
  json: {
    ...item,
    session_id: sessionId,
    message_count: messageCount,
    datos_clave: {
      ...datos,
      message_count: messageCount
    }
  }
}];

